    private List<ItemStack> pendingItems;
    @Override public void initGui(){if(pendingDescription!=null){put("description",String.join("\n",pendingDescription));pendingDescription=null;}if(pendingItems!=null){QuestCore.Task task=(QuestCore.Task)object;task.target="";task.targets.clear();task.filter=null;if(!pendingItems.isEmpty()){QuestItemFilter any=new QuestItemFilter();any.type="any";for(ItemStack s:pendingItems)if(s!=null){QuestItemFilter filter=new QuestItemFilter();filter.value=(String)Item.itemRegistry.getNameForObject(s.getItem());filter.meta=s.getItemDamage();filter.nbt=s.hasTagCompound()?s.getTagCompound().toString():"";filter.nbtMode=task.nbtMode;any.children.add(filter);}if(!any.children.isEmpty())task.filter=any;}pendingItems=null;}super.initGui();}
